import{_ as i,o as t,c as e,a2 as r}from"./chunks/framework.BqNd1sPY.js";const w=JSON.parse('{"title":"学习目标与边界","description":"","frontmatter":{},"headers":[],"relativePath":"00-从这里开始/学习目标与边界.md","filePath":"00-从这里开始/学习目标与边界.md"}'),s={name:"00-从这里开始/学习目标与边界.md"};function n(l,a,m,o,k,d){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="学习目标与边界" tabindex="-1">学习目标与边界 <a class="header-anchor" href="#学习目标与边界" aria-label="Permalink to &quot;学习目标与边界&quot;">​</a></h1><h2 id="_14-天后的能力" tabindex="-1">14 天后的能力 <a class="header-anchor" href="#_14-天后的能力" aria-label="Permalink to &quot;14 天后的能力&quot;">​</a></h2><ul><li>看懂一张 <a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a> 结构图以及训练循环伪代码。</li><li>解释<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>、<a href="/LLMTrain/05-速查表/术语速查#term-cross-entropy" class="wiki-term" data-wiki-title="cross-entropy" data-wiki-summary="衡量目标分布与预测分布差异的常用损失；分类时等价于正确类别的负对数概率。" data-wiki-misconception="交叉熵就是准确率。">交叉熵</a>、<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>下降和<a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>，不要求手推复杂偏导。</li><li>判断<a href="/LLMTrain/05-速查表/术语速查#term-pretraining" class="wiki-term" data-wiki-title="pretraining" data-wiki-summary="在大规模数据上学习通用模式的基础训练阶段。" data-wiki-misconception="预训练数据越多，模型回答就必然越真实。">预训练</a>、<a href="/LLMTrain/05-速查表/术语速查#term-lora" class="wiki-term" data-wiki-title="LoRA" data-wiki-summary="冻结大部分基础权重，用低秩矩阵学习权重增量的参数高效微调方法。" data-wiki-misconception="LoRA 会自动压缩推理模型或保证无损。">LoRA</a>、<a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a>、提示工程和 <a href="/LLMTrain/05-速查表/术语速查#term-agent" class="wiki-term" data-wiki-title="Agent" data-wiki-summary="让模型参与工具选择、读取结果和多步决策循环的应用结构。" data-wiki-misconception="Agent 可以脱离权限、预算和人工确认自主执行。">Agent</a> 的适用边界。</li><li>识别“<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>更多一定更好”“训练 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 越低越好”等常见误区。</li></ul><h2 id="_21-天后的作品" tabindex="-1">21 天后的作品 <a class="header-anchor" href="#_21-天后的作品" aria-label="Permalink to &quot;21 天后的作品&quot;">​</a></h2><p>你将得到一个自己训练的字符级微型语言模型。字符级不是现代商用 LLM 的主流分词方案，但它删掉了<a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">分词器</a>训练这一层复杂度，适合第一次完整理解训练链路。课程仍会讲 BPE、Unigram 等实际方案。</p><p>作品必须包含：</p><ul><li>固定的数据切分与随机种子。</li><li>可读的模型配置和<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>量。</li><li>训练与验证<a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">损失</a>。</li><li>训练前后相同提示词的输出。</li><li>至少一次改变单个变量的对照实验。</li><li>说明用途、限制和数据来源的模型卡。</li></ul><h2 id="暂不要求掌握" tabindex="-1">暂不要求掌握 <a class="header-anchor" href="#暂不要求掌握" aria-label="Permalink to &quot;暂不要求掌握&quot;">​</a></h2><ul><li>从头推导矩阵微积分。</li><li>多机多卡通信和自定义 CUDA 算子。</li><li>训练十亿<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>模型所需的集群运维。</li><li>背诵所有模型家族、Benchmark 或论文年份。</li></ul><p>这些主题在拓展知识库中保留入口，完成主线后再深入。</p>',10)])])}const p=i(s,[["render",n]]);export{w as __pageData,p as default};
